import sys

# Simple Greedy approach for maximum black coverage
def solve_greedy_coverage(N):
    """
    Uses a greedy heuristic to find the maximum number of black squares
    that can be covered by non-overlapping L-trominos.
    """

    # 1: Uncovered Black, 0: Uncovered White, -1: Covered
    board = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if (r + c) % 2 == 0:
                board[r][c] = 1 # Uncovered Black

    def get_available_trominos(current_board):
        """Generates all possible L-tromino placements on the current board state."""
        placements = []

        for r in range(N - 1):
            for c in range(N - 1):
                coords = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]

                # Test all 4 ways to remove one corner (forming an L)
                for i in range(4):
                    tromino_cells = [coords[j] for j in range(4) if j != i]

                    # Check if all three cells are currently available (not marked -1)
                    is_valid = True
                    cells_to_cover = []

                    for tr, tc in tromino_cells:
                        if current_board[tr][tc] == -1: # Check if already covered
                            is_valid = False
                            break
                        cells_to_cover.append((tr, tc))

                    if is_valid:
                        placements.append(cells_to_cover)
        return placements


    covered_count = 0

    while True:
        available_placements = get_available_trominos(board)
        if not available_placements:
            break

        best_placement = None
        max_newly_covered_black = -1

        # Greedy choice: pick the tromino that covers the most *uncovered* black squares
        for placement in available_placements:
            current_newly_covered_black = 0
            for r, c in placement:
                # Check if it's a black square (r+c is even) and currently uncovered (board[r][c] == 1)
                if (r + c) % 2 == 0 and board[r][c] == 1:
                    current_newly_covered_black += 1

            if current_newly_covered_black > max_newly_covered_black:
                max_newly_covered_black = current_newly_covered_black
                best_placement = placement

        if best_placement and max_newly_covered_black > 0:
            # Apply the best placement
            for r, c in best_placement:
                board[r][c] = -1
            covered_count += max_newly_covered_black
        else:
            # No available tromino covers any currently uncovered black square, or no trominos left
            break

    return covered_count

# --- Testing Small Boards ---
N_sizes = [5, 7]

results = {}
